using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;using System.Threading.Tasks;using V15Voice;
public static class VoiceReportUiTests {
 static int count,code;static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object C(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}static void Check(bool yes,string text){if(!yes)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}static IEnumerable<Control> Walk(Control o){foreach(Control c in o.Controls){yield return c;foreach(var d in Walk(c))yield return d;}}
 [STAThread]public static void Main(){Application.EnableVisualStyles();var f=new MainForm();f.Shown+=async(s,e)=>{var dismiss=new Timer{Interval=100};dismiss.Tick+=(a,b)=>{foreach(Form dialog in Application.OpenForms.Cast<Form>().Where(w=>w!=f&&w.Text=="V15 Voice Studio").ToArray())dialog.Close();};dismiss.Start();try{
 var tabs=(TabControl)F(f,"tabs");Check(Walk(tabs.TabPages[0]).OfType<Button>().Any(b=>b.Text=="Mở báo cáo lần chạy"),"Studio exposes last-run report button");Check(Walk(tabs.TabPages[1]).OfType<Button>().Any(b=>b.Text=="Mở báo cáo file"),"Queue exposes selected-file report button");
 string dir=Path.Combine(Path.GetTempPath(),"UI báo cáo "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string aPath=Path.Combine(dir,"first.srt"),bPath=Path.Combine(dir,"second.txt"),badPath=Path.Combine(dir,"bad.srt");string source="1\n00:00:00,000 --> 00:00:03,000\nThis is the original sentence.\n";File.WriteAllText(aPath,source);File.WriteAllText(bPath,"Đây là văn bản chưa có timeline.");File.WriteAllText(badPath,"INVALID_TIMELINE_FULL_INPUT_202");
 C(f,"LoadFile",aPath);var cat=(VoiceCatalog)F(f,"catalog");string key=((VoiceItem)((ComboBox)F(f,"voices")).SelectedItem).Key;cat.SaveNote(key,"VOICE_NOTE_202_REVIEW");((ComboBox)F(f,"breathMode")).SelectedIndex=2;
 var input=(List<Cue>)F(f,"cues");var context=(VoiceReportContext)C(f,"ReportContext",aPath,input,null);string snapshot=context.SourceCues[0].Text;input[0].Text="Modified after snapshot";Check(context.SourceCues[0].Text==snapshot,"Source metadata is snapshotted before later mutations");C(f,"LoadFile",aPath);
 await (Task)C(f,"Export");string first=(string)F(f,"lastVoiceReport");Check(File.Exists(first)&&Path.GetDirectoryName(first)==dir,"Single export creates automatic report even when model is missing");string text=File.ReadAllText(first);Check(text.Contains("Kết quả: THẤT BẠI")&&text.Contains("VOICE_NOTE_202_REVIEW")&&text.Contains("This is the original sentence."),"Failure report includes voice notes and complete source content");Check(text.Contains("Mã kết quả app: MODEL_PREFLIGHT_FAILED")&&text.Contains("Bước phát sinh lỗi: MODEL"),"UI missing-model export reports model phase/code");Check(!File.Exists(Path.ChangeExtension(aPath,"wav")),"Missing-model report does not pretend WAV succeeded");
 var grid=(DataGridView)F(f,"grid");grid.Rows[0].Cells[1].Value="bad_time";await (Task)C(f,"Export");string early=(string)F(f,"lastVoiceReport");Check(File.Exists(early)&&early!=first&&File.ReadAllText(early).Contains("Timecode không hợp lệ"),"Invalid grid options/input before Renderer also produce an error report");Check(File.ReadAllText(early).Contains("Mã kết quả app: INPUT_OR_SETUP_FAILED"),"UI pre-render validation reports input phase/code");Check(File.ReadAllText(aPath)==source,"Error reporting leaves source file unchanged");
 C(f,"LoadFile",aPath);((ComboBox)F(f,"breathMode")).SelectedIndex=2;((ComboBox)F(f,"mode")).SelectedIndex=2;C(f,"AddFiles",(object)new[]{aPath,bPath,badPath});await (Task)C(f,"ExportBatch");var jobs=(List<BatchJob>)F(f,"jobs");Check(jobs.Count==3&&jobs.All(j=>File.Exists(j.ReportPath)),"Every attempted or import-failed queue file gets its own report");Check(jobs.Single(j=>j.InputPath==badPath).State==JobState.ImportFailed&&File.ReadAllText(jobs.Single(j=>j.InputPath==badPath).ReportPath).Contains("INVALID_TIMELINE_FULL_INPUT_202"),"Unparseable input is included verbatim in import-failure report");Check(jobs.Where(j=>j.State==JobState.Failed).Count()==2,"A failed file does not stop other queued files being reported");Check(File.ReadAllText(jobs.Single(j=>j.InputPath==bPath).ReportPath).Contains("TXT · chưa có timeline nguồn"),"TXT report never treats draft duration as a measured source timeline");Check(((DataGridView)F(f,"jobGrid")).Rows.Cast<DataGridViewRow>().All(r=>Convert.ToString(r.Cells[5].Value).Contains("Báo cáo:")),"Queue table displays report path for successful report saves");
 Check(File.ReadAllText(jobs.Single(j=>j.InputPath==aPath).ReportPath).Contains("Trạng thái chặng: 0 đạt; 0 lỗi; 0 dừng; 1 chưa chạy"),"Queue preflight failure retains full anchored plan");C(f,"SaveSession");string state=(string)F(f,"stateDir");var restored=QueueStore.Load(Path.Combine(state,"queue.xml"));Check(restored.Count==3&&restored.All(j=>File.Exists(j.ReportPath)),"Report paths persist for valid and import-failed jobs across reload");Check(!(bool)F(f,"busy"),"Report failures restore UI controls");
 Console.WriteLine("TOTAL REPORT UI "+count+" passed.");
 }catch(Exception ex){Console.WriteLine(ex);code=1;}finally{dismiss.Stop();dismiss.Dispose();f.Close();}};Application.Run(f);Environment.Exit(code);}
}
